import sys

KINDS = ['asset', 'liability', 'income', 'expense']
LIMIT = 10 ** 12
ARGC = {'OPEN': 2, 'POST': 2, 'MOVE': 3, 'CLOSE': 1, 'REPORT': 0}
LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'
DIGITS = '0123456789'


class Account:
    def __init__(self, name, kind):
        self.name = name
        self.kind = kind
        self.balance = 0
        self.posts = 0


def fmt_cents(c):
    sign = '-' if c < 0 else ''
    a = -c if c < 0 else c
    return '%s%d.%02d' % (sign, a // 100, a % 100)


def is_digits(s):
    if len(s) == 0:
        return False
    for ch in s:
        if ch not in DIGITS:
            return False
    return True


def parse_amount(t):
    neg = False
    if t.startswith('-'):
        neg = True
        t = t[1:]
    if '.' in t:
        i = t.index('.')
        whole = t[:i]
        frac = t[i + 1:]
        if len(frac) != 2 or not is_digits(frac):
            return None
    else:
        whole = t
        frac = '00'
    if len(whole) < 1 or len(whole) > 11 or not is_digits(whole):
        return None
    v = int(whole) * 100 + int(frac)
    if v > LIMIT:
        return None
    return -v if neg else v


def valid_name(s):
    if len(s) < 1 or len(s) > 12:
        return False
    if s[0] not in LETTERS:
        return False
    for ch in s[1:]:
        if ch not in LETTERS and ch not in DIGITS and ch not in '_-':
            return False
    return True


def row(a, b, c, d):
    return '%-12s %-9s %5s %16s' % (a, b, c, d)


def report(accounts, out):
    out.append(row('ACCOUNT', 'KIND', 'POSTS', 'BALANCE'))
    accs = list(accounts.values())
    accs.sort(key=lambda a: (KINDS.index(a.kind), -a.balance, a.name))
    tp = 0
    tb = 0
    for a in accs:
        out.append(row(a.name, a.kind, str(a.posts), fmt_cents(a.balance)))
        tp += a.posts
        tb += a.balance
    out.append(row('TOTAL', '', str(tp), fmt_cents(tb)))


def execute(cmd, args, accounts, out):
    if cmd not in ARGC:
        return 'unknown command'
    if len(args) != ARGC[cmd]:
        return 'wrong argument count'
    if cmd == 'OPEN':
        name, kind = args
        if not valid_name(name):
            return 'bad name'
        if kind not in KINDS:
            return 'bad kind'
        if name in accounts:
            return 'duplicate account'
        accounts[name] = Account(name, kind)
        return None
    if cmd == 'POST':
        name, amt = args
        if name not in accounts:
            return 'unknown account'
        v = parse_amount(amt)
        if v is None:
            return 'bad amount'
        acc = accounts[name]
        acc.balance += v
        acc.posts += 1
        return None
    if cmd == 'MOVE':
        src, dst, amt = args
        if src not in accounts:
            return 'unknown account'
        if dst not in accounts:
            return 'unknown account'
        if src == dst:
            return 'same account'
        v = parse_amount(amt)
        if v is None:
            return 'bad amount'
        if v <= 0:
            return 'amount must be positive'
        a = accounts[src]
        b = accounts[dst]
        a.balance -= v
        a.posts += 1
        b.balance += v
        b.posts += 1
        return None
    if cmd == 'CLOSE':
        name = args[0]
        if name not in accounts:
            return 'unknown account'
        if accounts[name].balance != 0:
            return 'nonzero balance'
        del accounts[name]
        return None
    report(accounts, out)
    return None


def main():
    data = sys.stdin.read()
    lines = data.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    accounts = {}
    out = []
    ok = 0
    errors = 0
    lineno = 0
    for line in lines:
        lineno += 1
        toks = [t for t in line.replace('\t', ' ').split(' ') if t != '']
        if not toks or toks[0].startswith('#'):
            continue
        err = execute(toks[0], toks[1:], accounts, out)
        if err is None:
            ok += 1
        else:
            errors += 1
            out.append('line %d: error: %s' % (lineno, err))
    out.append('ok=%d errors=%d' % (ok, errors))
    sys.stdout.write('\n'.join(out) + '\n')


main()
